#include <iostream>
#include <stdexcept>
#include <vector>
#include <utility>

std::vector<int> make_buffer(int n) {
    if (n < 0)
        throw std::invalid_argument("buffer size must be non-negative");

    std::vector<int> v;
    v.reserve(static_cast<std::size_t>(n));
    for (int i = 0; i < n; ++i) v.push_back(i);
    return v;
}

void consume(std::vector<int> v) {
    std::cout << "got " << v.size() << " elements\n";
}

int main() {
    consume(make_buffer(5));

    auto big = make_buffer(1000);
    consume(std::move(big));

}

#include <algorithm>
#include <cstddef>
#include <stdexcept>

class IntArray {
    int* data;
    std::size_t size;
public:
    explicit IntArray(std::size_t n)
        : data(n != 0 ? new int[n]() : nullptr), size(n) {}

    ~IntArray() { delete[] data; }

    IntArray(const IntArray& o)
        : data(o.size ? new int[o.size] : nullptr), size(o.size) {
        if (size != 0) std::copy_n(o.data, size, data);
    }

    IntArray& operator=(const IntArray& o) {
        if (this == &o) return *this;
        int* nd = o.size ? new int[o.size] : nullptr;
        if (o.size != 0) std::copy_n(o.data, o.size, nd);
        delete[] data;
        data = nd;
        size = o.size;
        return *this;
    }

    IntArray(IntArray&& o) noexcept
        : data(o.data), size(o.size) {
        o.data = nullptr;
        o.size = 0;
    }

    IntArray& operator=(IntArray&& o) noexcept {
        if (this == &o) return *this;
        delete[] data;
        data = o.data;
        size = o.size;
        o.data = nullptr;
        o.size = 0;
        return *this;
    }

    int& at(std::size_t i) {
        if (i >= size) throw std::out_of_range("IntArray::at");
        return data[i];
    }
    const int& at(std::size_t i) const {
        if (i >= size) throw std::out_of_range("IntArray::at");
        return data[i];
    }
    std::size_t getSize() const noexcept { return size; }
};
